{"command": "python3 -c '
import requests
from io import BytesIO

class FileWrapper:
    def __init__(self, fileobj):
        self._fileobj = fileobj

    def __getattr__(self, name):
        if name == "read":
            return self._fileobj.read
        raise AttributeError(name)

def test_getattr_file_wrapper():
    content = b"hello world"
    fileobj = BytesIO(content)
    wrapper = FileWrapper(fileobj)

    files = {"file": wrapper}
    from requests.models import Request
    req = Request("POST", "http://httpbin.org/post", files=files)
    prepared = req.prepare()

    assert content in prepared.body
    print("Success!")

if __name__ == "__main__":
    try:
        test_getattr_file_wrapper()
    except Exception as e:
        print(f"Failure: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
'"}

